#!/usr/bin/env bash
# HOME LAYOUT FIX — (1) tam-ekran odadan dönüşte padding sıfırlanır (RECEPTION_PADDING_V1),
# (2) iOS font boosting kapatılır (TEXTSIZE_NOBOOST_V1). Rule 5. Idempotent.
set -e
cd /opt/krb-assessment
if [ -f shells/saha.js ]; then SAHA=shells/saha.js; else SAHA=$(find . -maxdepth 3 -name saha.js -not -path '*/backups/*' -not -path '*/node_modules/*'|head -1); fi
[ -f "$SAHA" ] || { echo "HATA: saha.js yok"; exit 1; }
cp "$SAHA" "$SAHA.bak.$(date +%s)"
SDIR=$(dirname "$SAHA")
printf '%s' '' | base64 -d > "$SDIR/ebatgeri_padding.py"
printf '%s' '' | base64 -d > "$SDIR/textsize_fix.py"
( cd "$SDIR" && python3 ebatgeri_padding.py && python3 textsize_fix.py ) && rm -f "$SDIR/ebatgeri_padding.py" "$SDIR/textsize_fix.py"
node --check "$SAHA" && echo SAHA_OK
docker build -t krb-assessment:secure .
docker compose up -d --force-recreate krb-assessment
sleep 4
echo "== verify (2 marker beklenir) =="
docker exec krb-assessment sh -c "grep -c 'RECEPTION_PADDING_V1\|TEXTSIZE_NOBOOST_V1' /app/shells/saha.js" || true
echo "== DONE =="
